namespace sv_e47abe7522684db3872692d0e81612e6.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Because Blazor Server scopes DI to the SignalR circuit, each user gets their own instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>Raised on the calling thread whenever the warehouse changes.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == _currentWarehouseId)
            return;

        if (AvailableWarehouses.All(w => w.Id != warehouseId))
            throw new ArgumentException($"Unknown warehouse: {warehouseId}");

        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_e47abe7522684db3872692d0e81612e6.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when fresh data arrives. Each circuit (user) gets
/// its own instance, so warehouse selections are independent.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestLowStockCount { get; private set; }

    /// <summary>Raised after <see cref="RefreshAsync"/> stores new data.</summary>
    public event Action? OnAlertDataChanged;

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate I/O latency
        int count = _random.Next(0, 16); // 0..15
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data for <paramref name="warehouseId"/>, stores it in
    /// <see cref="LatestLowStockCount"/>, and raises <see cref="OnAlertDataChanged"/>
    /// so every subscriber updates — not just the component that triggered the poll.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LatestLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnAlertDataChanged?.Invoke();
    }
}

