@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@using sv_e47abe7522684db3872692d0e81612e6.Services

<select class="form-select form-select-sm"
        style="width: auto; display: inline-block;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject InventoryAlertService AlertService
@using sv_e47abe7522684db3872692d0e81612e6.Services

<span class="badge @BadgeClass">@AlertService.LatestLowStockCount</span>

@code {
    private string BadgeClass =>
        AlertService.LatestLowStockCount > 0 ? "bg-danger" : "bg-secondary";

    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

