@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@using sv_e47abe7522684db3872692d0e81612e6.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @WarehouseState.CurrentWarehouseName
            <span class="text-muted fs-6">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LatestLowStockCount > 0)
            {
                <span class="badge bg-danger fs-5">@AlertService.LatestLowStockCount items below minimum</span>
            }
            else
            {
                <span class="badge bg-success fs-5">All stock levels OK</span>
            }
        </p>
        <p class="text-muted">
            @if (_polling)
            {
                <span>🔄 Polling every 10 seconds…</span>
            }
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _polling;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Kick off the first refresh and start the polling loop.
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _polling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }
        catch (TaskCanceledException)
        {
            // Expected when the component disposes or warehouse changes.
        }
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling for the newly selected warehouse.
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
            StateHasChanged();
        });
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
    }
}

